    ['bike', '自行车', [0.55, 1.05, 1.75], 'Old city bicycle resting on a kickstand, silver frame, wire basket and rear rack. Front points Z+.'],
    ['cart', '早餐推车', [2, 2.2, 1.2], 'Compact Chinese street breakfast cart with stainless worktop, glass food case, steamer pots, wheels and faded yellow canopy. Serving side faces Z+, small 早餐 lettering.'],
    ['crates', '菜筐货堆', [1.1, 0.85, 0.8], 'Standalone small stack of green plastic vegetable crates, several filled with leafy vegetables, one cardboard box, irregular practical stacking.'],
    ['bins', '分类垃圾桶', [1.4, 1.05, 0.65], 'Pair of wheeled neighborhood waste bins, green and gray, closed lids, faded Chinese sorting labels facing Z+.'],
    ['pole', '巷口电杆', [0.45, 9, 0.45], 'One slender weathered concrete utility pole, base Y=0, dark distribution crossarm and ceramic insulators near Y=8.6, small attached street lamp facing Z+, cable fasteners.'],
    ['wire', '架空线束', [4, 0.18, 0.15], 'Single short span of three black overhead utility cables along local X, canonical span 4m with endpoints at X=-2 and X=2 at Y=0; slight downward sag at center. No poles or ground attachments. Joining ends are bare.'],
    ['bench', '街边长凳', [1.8, 0.85, 0.65], 'Simple worn wooden neighborhood bench on concrete feet, seating faces Z+, base at Y=0.'],
    ['tree', '榕树', [6, 8, 6], 'One mature subtropical banyan street tree with branching trunk, dense rounded green canopy beginning above 2.3m and a small root flare. Base at Y=0.'],
    ['planter', '盆栽绿植', [0.65, 0.95, 0.65], 'One mismatched terracotta planter holding a leafy ornamental shrub, worn pot and dense green leaves.'],
    ['bollard', '防撞柱', [0.22, 0.8, 0.22], 'Single short black steel traffic bollard with yellow reflective stripes and rounded cap, base Y=0.'],
    ['notice', '社区公告栏', [2.4, 2.1, 0.35], 'Standalone Chinese community notice board on two steel legs, shallow green rain hood, glazed posters and 社区公告 heading, front Z+, base Y=0.'],
    ['ac', '外挂机', [0.8, 0.55, 0.4], 'Single weathered wall-mounted air conditioner outdoor unit with circular fan grille facing Z+, short steel support brackets and pipe elbows.'],
    ['stool', '塑料凳', [0.4, 0.45, 0.4], 'One low red plastic street-side stool with four legs, worn surface, base Y=0.']
  ];
  defs.forEach(function(d) {
    api.requireAsset({
      key: d[0], name: d[1], dimensions: d[2], prompt: d[3] + ' Coordinates: Y+ up, X+ right, Z+ front.',
      role: ['shop', 'entry', 'floor', 'balcony', 'end0', 'end', 'roof', 'hut'].indexOf(d[0]) >= 0 ? 'structure' : 'environment'
    });
  });
  function put(key, p, rot) {
    return api.place({ assetId: api.asset(key), position: p, rotationY: rot || 0 });
  }
  function sample(p) { return api.environmentSample(p); }
  function distance(a, b) { return Math.hypot(a[0] - b[0], a[1] - b[1]); }
  function segmentDistance(p, a, b) {
    const dx = b[0] - a[0], dz = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / (dx * dx + dz * dz)));
    return distance(p, [a[0] + t * dx, a[1] + t * dz]);
  }

  const spine = [];
  let previous = [1, -44];
  for (let i = 0; i < 8; i++) {
    const z = -44 + i * 12;
    const preferred = 2 + 3.4 * Math.sin(i * 0.83);
    let best = null;
    for (let j = -1; j <= 1; j++) {
      const p = [preferred + j * 2.5, z], s = sample(p);
      const cost = s.slope * 3 + Math.abs(s.height - sample(previous).height) + Math.abs(p[0] - previous[0]) * 0.09;
      if (!best || cost < best.cost) best = { p: p, cost: cost };
    }
    spine.push(best.p);
    previous = best.p;
  }
  const streets = [{ points: spine, width: 4.3 }];
  [1, 3, 5, 6].forEach(function(index, k) {
    [-1, 1].forEach(function(side) {
      const start = spine[index];
      const bendX = start[0] + side * (17 + (k % 2) * 2);
      let best = null;
      [-5, 0, 5].forEach(function(delta) {
        const mid = [bendX, start[1] + side * 3 + delta];
        const end = [side * 43, start[1] + side * 5 + delta];
        if (Math.abs(end[1]) > 43) return;
        const a = sample(start), b = sample(mid), c = sample(end);
        const cost = Math.abs(a.height - b.height) + Math.abs(b.height - c.height) + b.slope + c.slope;
        if (!best || cost < best.cost) best = { points: [start, mid, end], cost: cost };
      });
      if (best) streets.push({ points: best.points, width: k === 1 ? 3.5 : 2.8 });
    });
  });
  const routeIds = [];
  streets.forEach(function(street, i) {
    for (let j = 1; j < street.points.length; j++) {
      const a = street.points[j - 1], b = street.points[j];
      api.rampTerrain({
        start: a, end: b, width: street.width + 0.8,
        startHeight: sample(a).height, endHeight: sample(b).height,
        softness: 0.7, strength: 0.8
      });
    }
    routeIds.push(api.route({
      id: 'lane-' + i, points: street.points, width: street.width,
      curve: 'polyline', surface: 'paving', material: 'patched gray concrete with dark repaired seams'
    }));
  });

  const court = [spine[0][0] - 10, -39];
  const courtHeight = sample(court).height;
  api.sculptTerrain({ mode: 'flatten', point: court, radius: 6.5, strength: 1, targetHeight: courtHeight });
  const courtBase = sample(court).height;
  api.surface({ id: 'entrance-court', surface: 'paving', material: 'worn square concrete tiles', region: { kind: 'circle', center: court, radius: 6 } });
  api.route({ id: 'court-access', points: [court, [spine[0][0], -39]], width: 3, surface: 'paving' });

  const parcels = [];
  function nearStreet(p) {
    let minimum = 100;
    streets.forEach(function(s) {
      for (let i = 1; i < s.points.length; i++) minimum = Math.min(minimum, segmentDistance(p, s.points[i - 1], s.points[i]) - s.width / 2);
    });
    return minimum;
  }
  streets.forEach(function(street, streetIndex) {
    for (let j = 1; j < street.points.length; j++) {
      const a = street.points[j - 1], b = street.points[j], len = distance(a, b);
      const tangent = [(b[0] - a[0]) / len, (b[1] - a[1]) / len];
      for (let t = 4.6; t < len - 2.8; t += 8.0 + (streetIndex % 3) * 0.45) {
        [-1, 1].forEach(function(side) {
          const normal = [-tangent[1] * side, tangent[0] * side];
          const access = [a[0] + tangent[0] * t, a[1] + tangent[1] * t];
          const setback = street.width / 2 + 3.8 + ((j + streetIndex) % 2) * 0.25;
          const center = [access[0] + normal[0] * setback, access[1] + normal[1] * setback];
          if (Math.abs(center[0]) > 41.8 || Math.abs(center[1]) > 41.8 || distance(center, court) < 10.5) return;
          if (parcels.some(function(p) { return distance(p.center, center) < 8.0; })) return;
          const yaw = Math.atan2(-normal[0], -normal[1]);
          function local(x, z) {
            return [center[0] + x * Math.cos(yaw) + z * Math.sin(yaw), center[1] - x * Math.sin(yaw) + z * Math.cos(yaw)];
          }
          const corners = [local(-3.35, -3.1), local(3.35, -3.1), local(3.35, 3.1), local(-3.35, 3.1)];
          if (corners.some(function(p) { return nearStreet(p) < 0.4; })) return;
          const samples = corners.map(sample);
          const high = Math.max.apply(null, samples.map(function(s) { return s.height; }));
          const low = Math.min.apply(null, samples.map(function(s) { return s.height; }));
          if (high - low > 1.8) return;
          parcels.push({ center: center, yaw: yaw, access: access, local: local, height: sample(center).height, street: streetIndex });
        });
      }
    }
  });

  parcels.forEach(function(p, index) {
    const stories = 3 + ((index * 7 + p.street) % 3);
    api.sculptTerrain({ mode: 'flatten', point: p.center, radius: 4.65, strength: 1, targetHeight: p.height });
    const base = sample(p.center).height;
    const door = p.local(1.6, 3.12);
    const laneHeight = sample(p.access).height;
    api.rampTerrain({ start: p.access, end: door, width: 1.35, startHeight: laneHeight, endHeight: base, softness: 0.45, strength: 1 });
    api.route({ id: 'door-' + index, points: [p.access, door], width: 1.25, surface: 'paving' });
    function at(key, x, y, z) {
      const q = p.local(x, z);
      return put(key, [q[0], base + y, q[1]], p.yaw);
    }
    const ground = [
      at(index % 4 === 0 ? 'entry' : 'shop', -1.6, 0, 0),
      at('entry', 1.6, 0, 0)
    ];
    api.foundation({ under: ground, top: 'level', maxThickness: 2, material: 'stained concrete plinth' });
    at('end0', -3.2, 0, 0);
    at('end0', 3.2, 0, 0);
    for (let floor = 1; floor < stories; floor++) {
      const y = 3 + (floor - 1) * 2.8;
      at((floor + index) % 3 === 0 ? 'balcony' : 'floor', -1.6, y, 0);
      at((floor + index) % 2 === 0 ? 'balcony' : 'floor', 1.6, y, 0);
      at('end', -3.2, y, 0);
      at('end', 3.2, y, 0);
      if (floor === 1) at('ac', -2.5, y + 0.6, 3.15);
    }
    const top = 3 + (stories - 1) * 2.8;
    at('roof', -1.6, top, 0);
    at('roof', 1.6, top, 0);
    if (index % 2 === 0) at('hut', 1.5, top + 0.15, -1.5);
    at('tank', -1.5, top + 0.15, -1.6);
    if (index % 4 !== 0) at('awning', -1.6, 2.65, 3.4);
    if (index % 7 === 0) at('sign', -2.9, 3.4, 3.15);
    if (index % 3 === 0) at('scooter', -2.2, 0, 3.6);
    if (index % 5 === 0) at('planter', 2.75, 0, 3.45);
    if (index % 6 === 0) at('crates', -0.8, 0, 3.4);
  });

  function courtObject(key, x, z, yaw) {
    return put(key, [court[0] + x, courtBase, court[1] + z], yaw || 0);
  }
  courtObject('tree', -3.1, -1.5);
  courtObject('bench', -2.8, 1.6);
  courtObject('notice', 0, -4.4);
  courtObject('cart', 3.0, -1.8, -Math.PI / 2);
  courtObject('stool', 1.3, -1.2);
  courtObject('crates', 3.9, -3.2);
  courtObject('bins', -4, -3.8);
  courtObject('bike', 3.6, 2.2, 0.3);
  courtObject('scooter', 1.8, 3.5, 0.5);
  courtObject('planter', -1.6, -4.2);
  courtObject('bollard', 4.7, 1.3);
  courtObject('bollard', 4.7, -0.7);

  const poles = [];
  for (let i = 0; i < spine.length; i++) {
    const p = [spine[i][0] + 2.55, spine[i][1]];
    const y = sample(p).height;
    put('pole', [p[0], y, p[1]]);
    poles.push({ p: p, y: y + 8.6 });
  }
  for (let i = 1; i < poles.length; i++) {
    const a = poles[i - 1], b = poles[i];
    const n = Math.ceil(distance(a.p, b.p) / 4);
    for (let j = 0; j < n; j++) {
      const t0 = j / n, t1 = (j + 1) / n;
      const start = [a.p[0] + (b.p[0] - a.p[0]) * t0, a.p[1] + (b.p[1] - a.p[1]) * t0];
      const end = [a.p[0] + (b.p[0] - a.p[0]) * t1, a.p[1] + (b.p[1] - a.p[1]) * t1];
      api.placeBetween({
        assetId: api.asset('wire'), start: start, end: end,
        dimensions: [4, 0.18, 0.15], spanAxis: 'x', terrain: false,
        elevation: a.y + (b.y - a.y) * ((t0 + t1) / 2)
      });
    }
  }

  const greenery = api.sampleProbabilityField({
    bounds: { minX: -44, maxX: 44, minZ: -43, maxZ: 43 },
    candidates: 320, maxPoints: 20, minDistance: 2.3,
    seed: 2721816274,
    cluster: { strength: 0.6, scale: 10 }
  }, function(p) {
    if (distance(p, court) < 7 || nearStreet(p) < 0.8) return 0;
    if (parcels.some(function(b) { return distance(p, b.center) < 5.1; })) return 0;
    const s = api.environmentSample(p, { guideIds: routeIds });
    return s.slope < 0.5 ? 0.5 : 0.1;
  });
  greenery.forEach(function(p, i) {
    put('planter', p, i * 0.6);
  });
  api.spawn([spine[0][0], -43], 0);
}

function plan(api) {
  api.terrain('plain', { amplitude: 0.7, roughness: 0.25, seed: 3011432877 });

  const candidates = [[0, 0], [-3, 2], [3, -2]];
  let center = candidates[0];
  let bestRelief = Infinity;
  for (const p of candidates) {
    const samples = [
      api.environmentSample(p),
      api.environmentSample([p[0] - 28, p[1]]),
      api.environmentSample([p[0] + 28, p[1]]),
      api.environmentSample([p[0], p[1] - 23]),
      api.environmentSample([p[0], p[1] + 23])
    ];
    const heights = samples.map(s => s.height);
    const relief = Math.max.apply(null, heights) - Math.min.apply(null, heights);
    if (relief < bestRelief) {
      bestRelief = relief;
      center = p;
    }
  }

  const initialHeight = api.environmentSample(center).height;
  api.sculptTerrain({
    mode: 'flatten', point: center, radius: 37,
    strength: 1, targetHeight: initialHeight
  });
  const base = api.environmentSample(center).height;
  const cx = center[0];
  const cz = center[1];
  const count = 40;
  const angleStep = 2 * Math.PI / count;

  function point(rx, rz, angle) {
    return [cx + rx * Math.cos(angle), cz + rz * Math.sin(angle)];
  }
  function outline(rx, rz) {
    const points = [];
    for (let i = 0; i < count; i++) {
      points.push(point(rx, rz, (i - 0.5) * angleStep));
    }
    return points;
  }
  function declare(key, name, dimensions, prompt, role) {
    api.requireAsset({ key, name, dimensions, prompt, role: role || 'structure' });
    return api.asset(key);
  }

  api.surface({
    id: 'stone-precinct', surface: 'paving', material: 'weathered limestone cobbles',
    region: { kind: 'polygon', points: outline(35, 29) }
  });
  api.surface({
    id: 'arena-sand', surface: 'sand', material: 'warm ochre trampled sand',
    region: { kind: 'polygon', points: outline(16.7, 10.7) }
  });

  const arcade = declare(
    'arcade', '石拱廊', [4.3, 4, 2.2],
    'One medieval monumental limestone arcade bay. Y up, X span, Z+ outward front. Canonical span 4.3m, height 4m, depth 2.2m. A tall open round arch leads completely through the depth, flanked by half-width square piers at the X joining faces so neighboring bays form full piers. Heavy voussoirs, recessed inner arch, projecting imposts, weathered pale stone with dark seams. Continuous narrow floor and level cornice terminate exactly at both X joining faces. No end walls, no roof above cornice, no furniture in the passage.'
  );
  const upperArcade = declare(
    'upper-arcade', '上层拱廊', [4.3, 4, 2],
    'One upper-story medieval limestone amphitheater arcade bay, Y up, X span, Z+ outward. 4.3m wide, 4m high, 2m deep. Open round arch with low solid stone balustrade, paired half-piers at X joining faces, engaged slender pilaster and strongly recessed shadowed opening. Continuous floor and upper stringcourse join neighboring bays at equal height. Aged ivory limestone, restrained carved geometric medallion in spandrel. Flat joining faces, no end walls.'
  );
  const crown = declare(
    'crown', '顶层石墙', [4.3, 3, 1.8],
    'One medieval amphitheater attic wall bay, Y up, X span, Z+ outward front. Canonical width 4.3m, height 3m, depth 1.8m. Massive weathered limestone, a small centered arched window open through wall, engaged pilasters at shared half-pier ends, horizontal cornice and continuous crenellated stone parapet integrated within the 3m height. X joining faces flush, matching adjacent bays. No broad roof.'
  );
  const gate = declare(
    'gate', '主入口拱门', [4.3, 4, 2.2],
    'One monumental entrance bay for a medieval stone arena, Y up, X span, Z+ exterior front. 4.3m wide, 4m high, 2.2m deep. Fully open tall round arch with 3m clear passage and level stone sill, rusticated half-piers at X joining faces, heavy carved keystone, two attached bronze torch brackets and an ochre heraldic shield above arch. No gate leaf blocking access. Floor and cornice align with ordinary 4m arcade bays.'
  );
  const seats = declare(
    'seats', '阶梯看台', [3.6, 3, 4],
    'One solid masonry amphitheater seating wedge, Y up, X tangential span, Z+ front toward arena. Canonical 3.6m span, 4m radial depth, 3m total height. Six broad stone seating steps ascend from low front edge at Z+ to high back edge at Z-. Slightly tapered side faces allow a polygonal curved seating ring; rear wider than front. Solid load-bearing rubble stone core underneath, pale worn limestone treads. Flush side joining faces; no railings or end caps, no roof. Front begins at local base elevation.'
  );
  const stair = declare(
    'stair', '看台阶梯', [3.6, 3, 4],
    'One amphitheater radial stair wedge, Y up, X tangential span, Z+ faces arena. Canonical 3.6m wide, 4m deep, 3m high. A centered 1.5m wide walkable staircase of eighteen small risers climbs from low Z+ front to high Z- rear, flanked by short solid stone cheeks and narrow seating edges. Solid stone support below; slightly tapered sides meet neighboring seating wedges. Front starts at base elevation and rear finishes exactly 3m higher.'
  );
  const arenaWall = declare(
    'arena-wall', '竞技场围墙', [2.7, 1.4, 0.65],
    'One low medieval arena retaining barrier, Y up, X span, Z+ facing sandy arena. Canonical span 2.7m, height 1.4m, depth 0.65m. Rough limestone blocks and smooth rounded coping; flat X ends join other barrier segments. Narrow iron tie plates, chipped weathering. No doorway.'
  );
  const banner = declare(
    'banner', '纹章旗杆', [1.8, 5, 0.6],
    'One slender medieval dark timber flagpole on a small iron shoe, Y up, Z+ front. Long hanging deep crimson cloth banner with a simple faded gold lion emblem, iron crossbar and spear finial. Wind-bent fabric silhouette, no oversized pedestal.',
    'environment'
  );
  const brazier = declare(
    'brazier', '石座火盆', [1.1, 2.1, 1.1],
    'One medieval wrought iron brazier on a squat carved limestone pedestal, Y up, Z+ front. Open iron bowl with glowing coals and modest amber flames, four iron supports, soot staining and aged bronze rim.',
    'environment'
  );
  const booth = declare(
    'booth', '入口棚亭', [4.5, 3.4, 3.4],
    'One small medieval admissions and provisions booth, Y up, Z+ open customer front. Heavy dark oak posts, sloping faded ochre canvas canopy, stone footings, wooden counter along rear, two barrels and stacked pottery attached within footprint. Open front allows sheltered access.',
    'structure'
  );
  const tree = declare(
    'cypress', '柏树', [3, 10, 3],
    'One tall slender Mediterranean cypress, Y up. Dark olive green dense upright foliage, irregular tapered crown, visible short rough trunk and small root flare.',
    'environment'
  );

  function ring(rx, rz, y, assetId, dimensions, select, inward) {
    const points = outline(rx, rz);
    for (let i = 0; i < count; i++) {
      const chosen = select ? select(i) : assetId;
      if (!chosen) continue;
      const a = points[i];
      const b = points[(i + 1) % count];
      const angle = i * angleStep;
      const target = inward ? center : point(rx + 12, rz + 12, angle);
      api.placeBetween({
        assetId: chosen, start: a, end: b,
        dimensions: dimensions, spanAxis: 'x',
        terrain: false, elevation: y, frontTarget: target
      });
    }
  }

  // The load-bearing facade surrounds open concentric seating and a sandy arena.
  ring(30, 24, base, arcade, [4.3, 4, 2.2],
    i => i === 0 || i === 20 ? gate : arcade, false);
  ring(30, 24, base + 4, upperArcade, [4.3, 4, 2], null, false);
  ring(30, 24, base + 8, crown, [4.3, 3, 1.8], null, false);

  for (let tier = 0; tier < 3; tier++) {
    const rx = 19 + tier * 4;
    const rz = 13 + tier * 4;
    ring(rx, rz, base + tier * 3, seats, [3.6, 3, 4],
      i => {
        if (i === 0 || i === 20) return null;
        return i === 10 || i === 30 ? stair : seats;
      }, true);
  }
  ring(16.7, 10.7, base, arenaWall, [2.7, 1.4, 0.65],
    i => i === 0 || i === 20 || i === 10 || i === 30 ? null : arenaWall, true);

  api.route({
    id: 'east-gate-approach',
    points: [[cx + 16, cz], [cx + 31, cz], [cx + 39, cz + 1], [45, 7]],
    width: 3, curve: 'catmull-rom', surface: 'paving',
    material: 'worn limestone paving'
  });
  api.route({
    id: 'west-gate-approach',
    points: [[cx - 16, cz], [cx - 31, cz], [-40, cz - 2], [-46, -12]],
    width: 3, curve: 'catmull-rom', surface: 'paving',
    material: 'worn limestone paving'
  });
  const promenade = outline(33.4, 27.4);
  promenade.push(promenade[0]);
  api.route({
    id: 'outer-promenade', points: promenade, width: 3,
    curve: 'polyline', surface: 'paving', material: 'limestone cobbles'
  });

  for (const side of [-1, 1]) {
    for (const dz of [-4, 4]) {
      api.place({
        assetId: brazier,
        position: [cx + side * 32.5, base, cz + dz],
        terrain: false
      });
    }
  }
  for (const i of [3, 8, 13, 18, 23, 28, 33, 38]) {
    const p = point(30, 24, i * angleStep);
    api.place({
      assetId: banner, position: [p[0], base + 11, p[1]],
      terrain: false, rotationY: -i * angleStep
    });
  }

  for (const side of [-1, 1]) {
    const p = [cx + side * 35.5, cz - 9];
    const obj = api.place({
      assetId: booth, position: p,
      rotationY: side === 1 ? -Math.PI / 2 : Math.PI / 2
    });
    api.foundation({
      under: [obj], top: 'level', maxThickness: 1,
      material: 'rough limestone'
    });
    api.route({
      id: side === 1 ? 'east-booth-access' : 'west-booth-access',
      points: [[cx + side * 33, cz - 9], [cx + side * 33, cz - 3], [cx + side * 34, cz]],
      width: 1.8, surface: 'paving'
    });
  }

  api.grass('peripheral-meadow', {
    kind: 'polygon', points: [[-47, -47], [47, -47], [47, 47], [-47, 47]]
  }, { preset: 'meadow', density: 0.22, height: 0.18 });

  const trees = api.sampleProbabilityField({
    bounds: { minX: -44, maxX: 44, minZ: -44, maxZ: 44 },
    maxPoints: 24, candidates: 220, minDistance: 5,
    seed: 3011432877
  }, p => {
    const x = p[0] - cx;
    const z = p[1] - cz;
    const ellipse = x * x / (38 * 38) + z * z / (33 * 33);
    if (ellipse < 1 || Math.abs(z) < 13) return 0;
    const sample = api.environmentSample(p);
    return sample.slope < 0.45 ? 0.65 : 0.1;
  });
  for (const p of trees) {
    api.place({ assetId: tree, position: p, rotationY: Math.random() * Math.PI * 2 });
  }

  api.spawn([43, 7], -100);
}

function plan(api) {
  api.terrain('valley', { amplitude: 13, roughness: 0.42, seed: api.seed });
  const riverPoints = [[3, -47], [1, -32], [5, -16], [7, 0], [5, 17], [9, 33], [12, 47]];
  const river = api.water('valley-stream', {
    type: 'river',
    points: riverPoints,
    width: 4,
    depth: 1.5
  });

  function sample(p) {
    return api.environmentSample(p, { waterId: river });
  }
  function distance(a, b) {
    return Math.hypot(a[0] - b[0], a[1] - b[1]);
  }
  function segmentDistance(p, a, b) {
    const dx = b[0] - a[0], dz = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / (dx * dx + dz * dz || 1)));
    return distance(p, [a[0] + t * dx, a[1] + t * dz]);
  }

  const west = [[-11, -37], [-13, -27], [-10, -16], [-12, -5], [-10, 7], [-7, 18], [-8, 30], [-3, 40]];
  const east = [[20, -37], [21, -27], [23, -16], [25, -5], [23, 7], [23, 18], [25, 30], [27, 40]];
  function inspect(points) {
    let climb = 0, steep = 0;
    let last = sample(points[0]).height;
    for (const p of points) {
      const s = sample(p);
      climb += Math.abs(s.height - last);
      steep += s.slope;
      last = s.height;
    }
    return { climb: climb, steep: steep };
  }
  const w = inspect(west), e = inspect(east);
  const main = (w.steep + w.climb * 0.2 <= e.steep + e.climb * 0.2) ? west : east;
  const side = main === west ? -1 : 1;
  const outer = main.slice(1, 7).map(function(p, i) {
    return [p[0] + side * (14 + (i === 2 || i === 3 ? 1 : 0)), p[1] + (i % 2 ? 2 : -1)];
  });
  for (const p of outer) sample(p);

  const lanes = [];
  function lane(id, points, width) {
    for (let i = 0; i < points.length - 1; i++) {
      const a = sample(points[i]), b = sample(points[i + 1]);
      api.rampTerrain({
        start: points[i], end: points[i + 1], width: width + 0.8,
        startHeight: a.height, endHeight: b.height,
        softness: 0.8, strength: 0.8
      });
    }
    const routeId = api.route({
      id: id, points: points, width: width,
      curve: 'polyline', surface: 'paving',
      material: 'irregular worn grey limestone cobbles'
    });
    lanes.push({ points: points, width: width, id: routeId });
    return routeId;
  }
  lane('valley-lane', main, 3.2);
  lane('upper-lane', outer, 2.4);
  lane('south-climb', [main[1], [main[1][0] + side * 7, main[1][1] - 4], outer[0]], 2.3);
  lane('middle-climb', [main[3], [main[3][0] + side * 7, main[3][1] + 3], outer[2]], 2.2);
  lane('north-climb', [main[6], [main[6][0] + side * 7, main[6][1] + 4], outer[5]], 2.3);

  api.requireAsset({
    key: 'stone-house', name: '山谷石屋', role: 'structure',
    dimensions: [5.4, 7.5, 5.5], variants: 3,
    prompt: 'A compact inhabited mountain village house built from irregular grey limestone with pale mortar, two closely stacked floors and a steep dark slate gable roof. Y+ up, Z+ front entrance, X+ right. Footprint 5.4 by 5.5 metres, total height 7.5 metres. Ground-level front timber door, small recessed windows with weathered wooden shutters, modest chimney, copper gutter, narrow stone door threshold, restrained ivy on one side. Solid continuous walls and no wide porch, no projecting external stairs. Variations in masonry tone, shutter colour and roof ridge detail, preserving the same footprint and entrance.'
  });
  api.requireAsset({
    key: 'chapel', name: '石砌小教堂', role: 'structure',
    dimensions: [7, 11, 10],
    prompt: 'A small rural mountain chapel of grey limestone, one simple narrow nave with slate gabled roof, front arched timber door at ground level and a slender integrated bell gable rising above the front wall. Y+ up, Z+ front, X+ right. Seven metre width, ten metre depth, eleven metre total height. Deep narrow windows, stone quoins, small iron bell, weathered masonry. Complete simple building with no separate wings, no surrounding ground or enclosure.'
  });
  api.requireAsset({
    key: 'fountain', name: '村庄水槽', role: 'environment',
    dimensions: [2.8, 1.8, 1.5],
    prompt: 'A communal mountain village limestone water trough, rectangular basin with thick worn rim, short rear stone pillar and bronze spout pouring a thin stream into the basin. Y+ up, Z+ front. Weathered pale grey stone and subtle moss at water level.'
  });
  api.requireAsset({
    key: 'tree', name: '山谷阔叶树', role: 'environment',
    dimensions: [5, 9, 5],
    prompt: 'A mountain deciduous tree with a crooked grey trunk and airy irregular crown of small muted green leaves. Y+ up, natural branching, exposed base, no ground patch.'
  });
  api.requireAsset({
    key: 'pine', name: '山坡松树', role: 'environment',
    dimensions: [4.5, 11, 4.5],
    prompt: 'A slender mountain pine with a textured brown trunk and uneven layered branches bearing dark green needles. Y+ up. Natural open silhouette, no ground patch.'
  });
  api.requireAsset({
    key: 'supplies', name: '柴薪木桶', role: 'environment',
    dimensions: [1.8, 1.3, 0.9],
    prompt: 'One compact village doorstep supply group: neatly stacked split firewood under a small weathered timber cover, with a single wooden barrel beside it. Y+ up, Z+ front. Fits within 1.8 metre width and 0.9 metre depth.'
  });

  const square = [main[4][0] - side * 3.5, main[4][1] + 1];
  const squareSample = sample(square);
  api.sculptTerrain({ mode: 'flatten', point: square, radius: 5, targetHeight: squareSample.height, strength: 0.9 });
  sample(square);
  api.surface({
    id: 'village-square', surface: 'paving',
    material: 'worn pale limestone setts',
    region: { kind: 'circle', center: square, radius: 4.8 }
  });
  api.route({ id: 'square-entry', points: [main[4], square], width: 3, surface: 'paving' });
  const fountainPoint = [square[0], square[1] + 2.5];
  const fountain = api.place({ assetId: api.asset('fountain'), position: fountainPoint });
  api.foundation({ under: [fountain], top: 'level', maxThickness: 0.8, material: 'limestone' });

  const chapelPoint = [outer[3][0] + side * 7, outer[3][1] + 1];
  const chapelGround = sample(chapelPoint);
  api.sculptTerrain({ mode: 'flatten', point: chapelPoint, radius: 6.3, targetHeight: chapelGround.height, strength: 0.85 });
  sample(chapelPoint);
  const chapelYaw = Math.atan2(-side, 0);
  const chapel = api.place({
    assetId: api.asset('chapel'), position: chapelPoint, rotationY: chapelYaw
  });
  api.foundation({ under: [chapel], top: 'level', maxThickness: 4, material: 'rough limestone retaining masonry' });
  const chapelDoor = [chapelPoint[0] - side * 5, chapelPoint[1]];
  lane('chapel-access', [outer[3], chapelDoor], 2.5);

  const occupied = [{ p: chapelPoint, r: 6.2 }];
  let count = 0;
  const frontageLanes = lanes.slice(0, 2);
  for (let li = 0; li < frontageLanes.length; li++) {
    const line = frontageLanes[li];
    for (let i = 0; i < line.points.length - 1; i++) {
      const a = line.points[i], b = line.points[i + 1];
      const length = distance(a, b);
      const tx = (b[0] - a[0]) / length, tz = (b[1] - a[1]) / length;
      const slots = Math.max(1, Math.floor(length / 6));
      for (let j = 0; j < slots; j++) {
        const t = (j + 0.5) / slots;
        const access = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
        for (const direction of [-1, 1]) {
          const setback = line.width / 2 + 3.2 + Math.random() * 0.45;
          const nx = -tz * direction, nz = tx * direction;
          const p = [access[0] + nx * setback, access[1] + nz * setback];
          if (Math.abs(p[0]) > 42 || Math.abs(p[1]) > 42) continue;
          if (distance(p, square) < 8.1) continue;
          if (occupied.some(function(o) { return distance(o.p, p) < o.r + 3.1; })) continue;
          let blocked = false;
          for (const road of lanes) {
            for (let k = 0; k < road.points.length - 1; k++) {
              if (segmentDistance(p, road.points[k], road.points[k + 1]) < road.width / 2 + 2.85) blocked = true;
            }
          }
          if (blocked) continue;
          const s = sample(p);
          if (s.waterDistance < 4.6) continue;
          const corners = [
            [p[0] + 2.5, p[1] + 2.5], [p[0] - 2.5, p[1] + 2.5],
            [p[0] + 2.5, p[1] - 2.5], [p[0] - 2.5, p[1] - 2.5]
          ].map(sample);
          const relief = Math.max.apply(null, corners.map(function(v) { return v.height; })) -
            Math.min.apply(null, corners.map(function(v) { return v.height; }));
          if (relief > 4.8) continue;
          const roadHeight = sample(access).height;
          const targetHeight = s.height * 0.4 + roadHeight * 0.6;
          api.sculptTerrain({
            mode: 'flatten', point: p, radius: 3.8,
            targetHeight: targetHeight, strength: 0.95
          });
          const revised = sample(p);
          const yaw = Math.atan2(-nx, -nz);
          const h = 6.4 + Math.random() * 2.2;
          const obj = api.place({
            assetId: api.asset('stone-house', count % 3),
            position: p, rotationY: yaw, dimensions: [5.4, h, 5.5]
          });
          api.foundation({
            under: [obj], top: 'level', maxThickness: 3.5,
            material: 'rough grey limestone matching the house walls'
          });
          const door = [p[0] - nx * 2.8, p[1] - nz * 2.8];
          api.rampTerrain({
            start: access, end: door, width: 1.5,
            startHeight: roadHeight, endHeight: revised.height,
            softness: 0.65, strength: 1
          });
          api.route({ id: 'door-path-' + count, points: [access, door], width: 1.2, surface: 'paving' });
          if (count % 4 === 0) {
            api.place({
              assetId: api.asset('supplies'),
              position: [door[0] + tx * 1.7, door[1] + tz * 1.7],
              rotationY: yaw
            });
          }
          occupied.push({ p: p, r: 3.05 });
          count++;
        }
      }
    }
  }

  const start = main[0];
  api.spawn(start, Math.atan2(main[1][0] - start[0], main[1][1] - start[1]) * 180 / Math.PI);
  api.grass('valley-meadow', {
    kind: 'polygon', points: [[-47, -47], [47, -47], [47, 47], [-47, 47]]
  }, { preset: 'meadow', density: 0.32, height: 0.3 });

  const trees = api.sampleProbabilityField({
    maxPoints: 85, candidates: 750, minDistance: 4,
    bounds: { minX: -43, maxX: 43, minZ: -43, maxZ: 43 },
    seed: api.seed + 13, cluster: { strength: 0.5, scale: 13 }
  }, function(p) {
    if (distance(p, square) < 8 || occupied.some(function(o) { return distance(p, o.p) < o.r + 4; })) return 0;
    for (const road of lanes) {
      for (let i = 0; i < road.points.length - 1; i++) {
        if (segmentDistance(p, road.points[i], road.points[i + 1]) < 4.5) return 0;
      }
    }
    const s = sample(p);
    if (s.waterDistance < 3) return 0;
    return 0.2 + 0.6 * Math.min(1, Math.abs(p[0]) / 35);
  });
  for (let i = 0; i < trees.length; i++) {
    const p = trees[i];
    const scale = 0.75 + Math.random() * 0.45;
    const pine = Math.abs(p[0]) > 27;
    api.place({
      assetId: api.asset(pine ? 'pine' : 'tree'), position: p,
      rotationY: Math.random() * Math.PI * 2,
      dimensions: pine ? [4.5 * scale, 11 * scale, 4.5 * scale] : [5 * scale, 9 * scale, 5 * scale]
    });
  }
}
